import os
import pandas as pd
from databricks.sdk import WorkspaceClient

# Initialize WorkspaceClient
w = WorkspaceClient()

# Read standardized data
df = pd.read_csv('data/combined_standardized.csv')

# Schema and table name
schema_name = os.environ['MLPAB_DATABRICKS_SCHEMA'].split('.')[-1]  # Extract schema name only
table_name = 'scaled290b1e'
full_table_name = f'workspace.{schema_name}.{table_name}'

# Write data to Delta table using Spark SQL
w.api_client.do(
    method='POST',
    path='/api/2.0/sql/statements/',
    body={
        'statement': f'CREATE TABLE IF NOT EXISTS {full_table_name} (row_id STRING, split STRING, f1 DOUBLE, f2 DOUBLE, f3 DOUBLE, f4 DOUBLE)',
        'warehouse_id': os.environ.get('DATABRICKS_SQL_WAREHOUSE_ID', 'default')
    }
)

# Write data to the table
for _, row in df.iterrows():
    w.api_client.do(
        method='POST',
        path='/api/2.0/sql/statements/',
        body={
            'statement': f'INSERT INTO {full_table_name} VALUES (\"{row[\"row_id\"]}\", \"{row[\"split\"]}\", {row[\"f1\"]}, {row[\"f2\"]}, {row[\"f3\"]}, {row[\"f4\"]})',
            'warehouse_id': os.environ.get('DATABRICKS_SQL_WAREHOUSE_ID', 'default')
        }
    )

# Register as a feature table
ft = w.api_client.do(
    method='POST',
    path='/api/2.0/feature-store/feature-tables',
    body={
        'name': full_table_name,
        'primary_keys': ['row_id'],
        'schema': [
            {'name': 'row_id', 'type': 'string'},
            {'name': 'split', 'type': 'string'},
            {'name': 'f1', 'type': 'double'},
            {'name': 'f2', 'type': 'double'},
            {'name': 'f3', 'type': 'double'},
            {'name': 'f4', 'type': 'double'}
        ],
        'online_store_spec': {
            'online_store_type': 'DELTASHARING'
        }
    }
)

print(f'Feature table {full_table_name} registered successfully.')
print(f'Feature table ID: {ft[\"feature_table_id\"]}')

# Enable online access
w.api_client.do(
    method='POST',
    path=f'/api/2.0/feature-store/feature-tables/{ft[\"feature_table_id\"]}/online-store',
    body={
        'online_store_spec': {
            'online_store_type': 'DELTASHARING'
        }
    }
)

print(f'Online access enabled for feature table {full_table_name}.')
""}

